import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    c = int(data[0].strip())
    n, m = map(int, data[1].split())
    if c == 1:
        res = n + m
    elif c == 2:
        res = n - m
    elif c == 3:
        res = n * m
    else:  # c == 4
        res = n / m
    if c == 4:
        print("{:.2f}".format(res))
    else:
        print(int(res))

if __name__ == "__main__":
    main()
